import os
from typing import Any, Dict, Optional

import boto3
from botocore.exceptions import ClientError


class EmailPasswordAccountManager:
    def __init__(self, region_name: Optional[str] = None):
        self.region_name = region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")
        if not self.region_name:
            raise ValueError("AWS_REGION or AWS_DEFAULT_REGION must be set")
        self.client = boto3.client("cognito-idp", region_name=self.region_name)

    def create_account(
        self,
        client_id: str,
        email: str,
        password: str,
        given_name: Optional[str] = None,
        family_name: Optional[str] = None,
        suppress_email: bool = False,
    ) -> Dict[str, Any]:
        params: Dict[str, Any] = {
            "ClientId": client_id,
            "Username": email,
            "Password": password,
            "UserAttributes": [{"Name": "email", "Value": email}],
        }
        if given_name:
            params["UserAttributes"].append({"Name": "given_name", "Value": given_name})
        if family_name:
            params["UserAttributes"].append({"Name": "family_name", "Value": family_name})

        try:
            sign_up_resp = self.client.sign_up(**params)
            result: Dict[str, Any] = {
                "user_sub": sign_up_resp.get("UserSub"),
                "user_confirmed": sign_up_resp.get("UserConfirmed", False),
                "code_delivery_details": sign_up_resp.get("CodeDeliveryDetails"),
            }

            if suppress_email and not result["user_confirmed"]:
                try:
                    self.client.admin_confirm_sign_up(UserPoolId=self._infer_user_pool_id(client_id), Username=email)
                    result["user_confirmed"] = True
                except Exception:
                    pass

            return result
        except ClientError as e:
            raise RuntimeError(f"Failed to create Cognito user: {e}") from e

    def _infer_user_pool_id(self, client_id: str) -> str:
        user_pool_id = os.getenv("COGNITO_USER_POOL_ID")
        if not user_pool_id:
            raise ValueError(
                "COGNITO_USER_POOL_ID must be set to use suppress_email/admin confirmation with Cognito"
            )
        return user_pool_id


def create_email_password_account(
    client_id: str,
    email: str,
    password: str,
    given_name: Optional[str] = None,
    family_name: Optional[str] = None,
    suppress_email: bool = False,
) -> Dict[str, Any]:
    manager = EmailPasswordAccountManager()
    return manager.create_account(
        client_id=client_id,
        email=email,
        password=password,
        given_name=given_name,
        family_name=family_name,
        suppress_email=suppress_email,
    )
